WITH CONTRACT_STARTS_CTE AS
(
	-- Contract starts base set
     SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE START_DATE IS NOT NULL
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
)
, CONTRACT_STOPS_CTE AS
(
	-- Contract stops base set
 	SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(ACTUAL_END_DATE_DATETIME__C AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE ACTUAL_END_DATE_DATETIME__C IS NOT NULL
        AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire')
)
, PERM_STARTS_CTE AS
(
	-- Perm starts base set
	SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
		,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
	FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
	WHERE START_DATE IS NOT NULL
		AND PLACEMENT_STATUS = 'Booked' 
		AND ELI_RECORD_TYPE_NAME__C = 'Permanent'
)
, CONSULTING_STARTS_CTE AS
(
	-- Consulting starts base set
    SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE START_DATE IS NOT NULL
		AND PLACEMENT_STATUS = 'Booked'
		AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END = 'Consulting'
)
, CONSULTING_STOPS_CTE AS
(
	-- Consulting stops base set
    SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(ACTUAL_END_DATE_DATETIME__C AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE ACTUAL_END_DATE_DATETIME__C IS NOT NULL
		AND PLACEMENT_STATUS = 'Booked'
		AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END = 'Consulting'
)
, DEALS_CTE AS
(
	-- Deals base set
    SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(CREATEDDATE AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
		,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE CREATEDDATE IS NOT NULL
)
, TOTAL_STARTS_CTE AS
(
	-- Total starts base set
    SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(START_DATE AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE START_DATE IS NOT NULL
		AND PLACEMENT_STATUS = 'Booked'
)
, TOTAL_STOPS_CTE AS
(
 -- Total stops base set
    SELECT 
		 PLACEMENT_HKEY
		,_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
		,CAST(ACTUAL_END_DATE_DATETIME__C AS DATE) AS FACT_DATE
		,CONTRACT_TYPE
        ,CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END AS RECORD_TYPE
		,DIVISION
		,DOMAIN
		,SEGMENT 
    FROM {{ ref('sat_bh4sf_placement_bvv_curr') }}
    WHERE ACTUAL_END_DATE_DATETIME__C IS NOT NULL
		AND PLACEMENT_STATUS = 'Booked'
        AND CASE WHEN CONSULTING_REVENUE__C = 'Yes' THEN 'Consulting' ELSE ELI_RECORD_TYPE_NAME__C END IN ('Contract','Contract To Hire','Consulting')
)
, FACT_DATE_CTE AS
(
	-- Fact date base set
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_STARTS_CTE
	UNION
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONTRACT_STOPS_CTE
	UNION
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM PERM_STARTS_CTE
	UNION
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_STARTS_CTE
	UNION
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM CONSULTING_STOPS_CTE
	UNION
	SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM DEALS_CTE
    UNION
    SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_STARTS_CTE
    UNION
    SELECT PLACEMENT_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
	FROM TOTAL_STOPS_CTE
    
)
SELECT 
      FD.PLACEMENT_HKEY
    , FD.AIRBYTE_DATE
    , FD.FACT_DATE
    , CAST(CASE WHEN CONTRACT_STARTS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN CONTRACT_STARTS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS CONTRACT_STARTS
	, CAST(CASE WHEN CONTRACT_STOPS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN CONTRACT_STOPS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS CONTRACT_STOPS
	, CAST(CASE WHEN PERM_STARTS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN PERM_STARTS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS PERM_STARTS
	, CAST(CASE WHEN CONSULTING_STARTS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN CONSULTING_STARTS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS CONSULTING_STARTS
	, CAST(CASE WHEN CONSULTING_STOPS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN CONSULTING_STOPS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS CONSULTING_STOPS
	, CAST(CASE WHEN DEALS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN DEALS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS DEALS
    ,CAST(CASE WHEN TOTAL_STARTS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN TOTAL_STARTS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS TOTAL_STARTS
    ,CAST(CASE WHEN TOTAL_STOPS_CTE.FACT_DATE IS NOT NULL THEN
					CASE WHEN TOTAL_STOPS_CTE.CONTRACT_TYPE = 'Part-Time' THEN '0.5' ELSE '1' END
				ELSE 0 END AS DECIMAL(10,1)) AS TOTAL_STOPS
	, FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT
FROM FACT_DATE_CTE FD
LEFT JOIN CONTRACT_STARTS_CTE CONTRACT_STARTS_CTE
ON FD.PLACEMENT_HKEY = CONTRACT_STARTS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = CONTRACT_STARTS_CTE.FACT_DATE
LEFT JOIN CONTRACT_STOPS_CTE CONTRACT_STOPS_CTE
ON FD.PLACEMENT_HKEY = CONTRACT_STOPS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = CONTRACT_STOPS_CTE.FACT_DATE
LEFT JOIN PERM_STARTS_CTE PERM_STARTS_CTE
ON FD.PLACEMENT_HKEY = PERM_STARTS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = PERM_STARTS_CTE.FACT_DATE
LEFT JOIN CONSULTING_STARTS_CTE CONSULTING_STARTS_CTE
ON FD.PLACEMENT_HKEY = CONSULTING_STARTS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = CONSULTING_STARTS_CTE.FACT_DATE
LEFT JOIN CONSULTING_STOPS_CTE CONSULTING_STOPS_CTE
ON FD.PLACEMENT_HKEY = CONSULTING_STOPS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = CONSULTING_STOPS_CTE.FACT_DATE
LEFT JOIN DEALS_CTE DEALS_CTE
ON FD.PLACEMENT_HKEY = DEALS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = DEALS_CTE.FACT_DATE
LEFT JOIN TOTAL_STARTS_CTE TOTAL_STARTS_CTE
ON FD.PLACEMENT_HKEY = TOTAL_STARTS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = TOTAL_STARTS_CTE.FACT_DATE
LEFT JOIN TOTAL_STOPS_CTE TOTAL_STOPS_CTE
ON FD.PLACEMENT_HKEY = TOTAL_STOPS_CTE.PLACEMENT_HKEY AND FD.FACT_DATE = TOTAL_STOPS_CTE.FACT_DATE
